import{_ as e,a,b as o}from"./chunks/ind-dsd-component.DI3Bmyu9.js";import{_ as r,a as s,b as i,c as n,d,e as l,f as c}from"./chunks/ind-published.CjzqkIwf.js";import{_ as h,a as p}from"./chunks/ind-public-data-structure.Bk53oDPn.js";import{_ as g}from"./chunks/ind-public-chart.BeYuNPiS.js";import{_ as u,o as m,c as f,ag as b}from"./chunks/framework.CxkNbRKf.js";const _="/nada-documentation/images/ind-public-chart-6-countries.png",E=JSON.parse('{"title":"Tutorial: your first indicator","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/content/indicators-tutorial.md","filePath":"admin-guide/content/indicators-tutorial.md","lastUpdated":1793155456000}'),A={name:"admin-guide/content/indicators-tutorial.md"};function D(w,t,y,I,k,S){return m(),f("div",null,[...t[0]||(t[0]=[b('<h1 id="tutorial-your-first-indicator" tabindex="-1">Tutorial: your first indicator <a class="header-anchor" href="#tutorial-your-first-indicator" aria-label="Permalink to &quot;Tutorial: your first indicator&quot;">​</a></h1><p>In this tutorial you publish the World Bank indicator <strong>SI.POV.DDAY</strong>, <em>Poverty headcount ratio at $3.00 a day (2021 PPP) (% of population)</em>, for 183 countries, directly in NADA. It takes about 15 minutes.</p><p>You will:</p><ol><li>import a data structure and its country codelist;</li><li>create the indicator from its metadata file;</li><li>upload its data;</li><li>add a thumbnail and publish;</li><li>explore the indicator in the catalog;</li><li>see what happens when you upload different data.</li></ol><p>If you are new to indicators, read <a href="./indicators-concepts.html">Key concepts</a> first. It uses the same example.</p><div class="info custom-block"><p class="custom-block-title">Before you begin</p><ul><li>NADA <strong>5.6</strong> or later, with <strong>MongoDB</strong> set up: see <a href="/nada-documentation/installation-guide/installation-mongodb.html">MongoDB setup</a>. The screenshots are from NADA 5.7.</li><li>A NADA account with permission to add and publish studies, and to manage data structures.</li><li>The sample files: download <a href="https://github.com/ihsn/nada-documentation/raw/main/examples/indicators/try_indicators.zip" target="_blank" rel="noreferrer">try_indicators.zip</a> and unzip it. The files are described in the <a href="https://github.com/ihsn/nada-documentation/tree/main/examples/indicators" target="_blank" rel="noreferrer">sample README</a>.</li></ul></div><hr><h2 id="step-1-import-the-data-structure" tabindex="-1">Step 1: Import the data structure <a class="header-anchor" href="#step-1-import-the-data-structure" aria-label="Permalink to &quot;Step 1: Import the data structure&quot;">​</a></h2><p>The data structure tells NADA what each column of the data means. The sample&#39;s data structure also contains the list of country codes and names.</p><ol><li>In the admin, go to <strong>Settings → Data structures</strong>.</li><li>Click <strong>Import JSON</strong> and choose <code>SI.POV.DDAY_dsd.json</code>.</li><li>Leave <strong>Overwrite</strong> off and click <strong>Import</strong>.</li></ol><p><img src="'+e+'" alt="Import DSD from JSON dialog"></p><p>NADA shows <em>Import finished. Codelists touched: 1.</em> and opens the new data structure, <em>WDI indicators by country and year</em>. It has five <strong>Components</strong>: <code>INDICATOR</code>, <code>INDICATOR_LABEL</code>, <code>REF_AREA</code>, <code>YEAR</code> and <code>VALUE</code>. Its status is <em>Draft</em>.</p><p><img src="'+a+'" alt="The imported data structure"></p><p><strong>Check:</strong></p><ul><li><p>Click <code>REF_AREA</code>. Its <strong>Column type</strong> is <code>geography</code>, and its <strong>Codelist</strong> is <code>CL_REF_AREA</code> (<code>WB_CL_REF_AREA_1.0</code>), whose codes are listed below.</p><p><img src="'+o+'" alt="The REF_AREA component and its codelist"></p></li><li><p>Click <strong>Validate</strong>. NADA shows <em>Validation passed.</em></p></li></ul><div class="tip custom-block"><p class="custom-block-title">Already imported?</p><p>If the import says the data structure already exists, it was imported before. Use the existing one and continue.</p></div><h2 id="step-2-create-the-indicator-from-its-metadata-file" tabindex="-1">Step 2: Create the indicator from its metadata file <a class="header-anchor" href="#step-2-create-the-indicator-from-its-metadata-file" aria-label="Permalink to &quot;Step 2: Create the indicator from its metadata file&quot;">​</a></h2><p>The file <code>SI.POV.DDAY_metadata.json</code> holds the indicator&#39;s metadata. It also names the data structure the indicator uses.</p><ol><li>Go to <strong>Studies → Manage studies</strong> and click <strong>Add study</strong>.</li><li>Under <strong>Import from file</strong>, choose the <strong>Collection</strong>, then choose <code>SI.POV.DDAY_metadata.json</code> as the <strong>Metadata file</strong>.</li><li>Click <strong>Submit</strong>.</li></ol><p><img src="'+r+'" alt="Add study, Import from file"></p><p>NADA recognizes the file as a time series, creates the indicator, and opens it. The <strong>Overview</strong> shows the title, the <strong>Reference No.</strong> <code>SI.POV.DDAY</code>, the years 1963–2025 and the 183 countries. The indicator is a <em>Draft</em>: it is not visible in the catalog yet.</p><p><img src="'+s+'" alt="The new indicator&#39;s Overview tab"></p><p><strong>Check:</strong> open the <strong>Metadata</strong> tab, then <strong>Indicator description → Title statement</strong>. <strong>Primary ID</strong> is <code>SI.POV.DDAY</code> and <strong>Name</strong> is the indicator&#39;s name. The other sections hold the definitions, methodology, sources and coverage from the file.</p><p><img src="'+i+'" alt="Metadata tab, Title statement"></p><h2 id="step-3-upload-the-data" tabindex="-1">Step 3: Upload the data <a class="header-anchor" href="#step-3-upload-the-data" aria-label="Permalink to &quot;Step 3: Upload the data&quot;">​</a></h2><ol><li><p>Open the <strong>Indicator data</strong> tab.</p><p>The <strong>Data structure</strong> field already shows <em>WDI indicators by country and year — WB_WDI_COUNTRY_YEAR_1.0</em>: the metadata file linked it.</p><p><img src="'+n+'" alt="Indicator data tab with the data structure linked"></p></li><li><p>Under <strong>Upload data (CSV)</strong>, choose <code>SI.POV.DDAY_data.csv</code> and click <strong>Import</strong>.</p></li></ol><p>NADA shows <em>Imported 2794 observation(s)</em> and <strong>Data attached 2,794</strong>. The <strong>Data preview</strong> below lists the rows.</p><p><img src="'+d+'" alt="Data uploaded"></p><p><strong>Check:</strong> open <strong>Dimension summaries</strong>. <code>REF_AREA</code> has <strong>183</strong> distinct codes and <strong>2794</strong> observations. These counts drive the country filter in the catalog.</p><p><img src="'+l+'" alt="Dimension summaries"></p><h2 id="step-4-add-a-thumbnail-and-publish" tabindex="-1">Step 4: Add a thumbnail and publish <a class="header-anchor" href="#step-4-add-a-thumbnail-and-publish" aria-label="Permalink to &quot;Step 4: Add a thumbnail and publish&quot;">​</a></h2><ol><li>Open the <strong>Overview</strong> tab. In the <strong>Thumbnail</strong> panel, click the pencil, choose <code>SI.POV.DDAY_thumbnail.jpg</code> and click <strong>Upload</strong>.</li><li>In the <strong>Status</strong> panel, click <strong>Draft</strong>. It changes to <strong>Published</strong>.</li></ol><p><img src="'+c+'" alt="Published indicator"></p><h2 id="step-5-explore-the-indicator-in-the-catalog" tabindex="-1">Step 5: Explore the indicator in the catalog <a class="header-anchor" href="#step-5-explore-the-indicator-in-the-catalog" aria-label="Permalink to &quot;Step 5: Explore the indicator in the catalog&quot;">​</a></h2><p>Click <strong>Preview study</strong> under the title to open the indicator&#39;s catalog page. The header shows the thumbnail, the title, <em>Angola, Albania, Argentina...and 180 more, 1963 - 2025</em>, and the reference ID.</p><p><img src="'+h+'" alt="Series description"></p><p>The page has five tabs:</p><ul><li><p><strong>Series description</strong>: the metadata.</p></li><li><p><strong>Chart &amp; data</strong>: an interactive chart. On the left, the <strong>Year</strong> slider and the <strong>Country</strong> list filter the data; the first country, Angola, is selected at first.</p><ol><li>Clear <strong>Angola</strong>, and select <strong>Albania</strong> and <strong>Argentina</strong>. The chart updates as you select.</li><li>Click <strong>Line</strong>.</li></ol><p>Argentina has a value for most years. Albania&#39;s values are separate points (1996, 2002, 2005…) because poverty is measured only in the years a household survey was run. <strong>Chart data</strong> below the chart lists the <strong>47</strong> values shown.</p><p><img src="'+g+'" alt="Chart &amp; data, Albania and Argentina"></p></li><li><p><strong>Table</strong>: the same data as a table, with countries as rows and years as columns. Use <strong>Filters</strong> and <strong>Layout</strong> to change it. The countries you selected on <strong>Chart &amp; data</strong> are kept when you switch tabs.</p></li><li><p><strong>Data API</strong>: how to get the data with the API, and a <strong>Data explorer</strong> with all 2,794 observations.</p></li><li><p><strong>Data structure</strong>: the five columns and their roles. Expand <code>REF_AREA</code> to see its 183 codes. <strong>Download JSON</strong> and <strong>Download SDMX/XML</strong> download the data structure.</p><p><img src="'+p+'" alt="Data structure tab"></p></li></ul><h2 id="step-6-see-how-uploads-work" tabindex="-1">Step 6: See how uploads work <a class="header-anchor" href="#step-6-see-how-uploads-work" aria-label="Permalink to &quot;Step 6: See how uploads work&quot;">​</a></h2><p>An upload always <strong>replaces</strong> all of an indicator&#39;s data.</p><ol><li>In the admin, on the <strong>Indicator data</strong> tab, choose <code>SI.POV.DDAY_data-6-countries.csv</code> and click <strong>Import</strong>.</li><li>NADA asks: <em>This import will replace all existing indicator observations for this study with the rows in your CSV. Continue?</em> Click <strong>OK</strong>.</li></ol><p><strong>Check:</strong> the tab shows <strong>Data attached 91</strong>. In the catalog, <strong>Chart &amp; data</strong> now has 6 countries, and the <strong>Year</strong> range is 1981–2024.</p><p><img src="'+_+'" alt="Chart after uploading the 6-country file"></p><p>Upload <code>SI.POV.DDAY_data.csv</code> again to restore all 2,794 rows.</p><hr><h2 id="what-you-did" tabindex="-1">What you did <a class="header-anchor" href="#what-you-did" aria-label="Permalink to &quot;What you did&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You created</th><th>Where</th><th>Shared?</th></tr></thead><tbody><tr><td>Data structure <code>WB_WDI_COUNTRY_YEAR_1.0</code></td><td><strong>Settings → Data structures</strong></td><td>Yes: any annual, country-level indicator can use it</td></tr><tr><td>Codelist <code>WB_CL_REF_AREA_1.0</code></td><td><strong>Settings → Codelists</strong></td><td>Yes</td></tr><tr><td>Indicator <code>SI.POV.DDAY</code>, with its metadata, data and thumbnail</td><td><strong>Studies → Manage studies</strong></td><td>No</td></tr></tbody></table><p>To publish another WDI indicator, repeat steps 2 to 5 with its own metadata and data files, and reuse the same data structure.</p><h2 id="clean-up" tabindex="-1">Clean up <a class="header-anchor" href="#clean-up" aria-label="Permalink to &quot;Clean up&quot;">​</a></h2><p>To remove the tutorial content:</p><ol><li>Delete the indicator: open it and click <strong>Delete study</strong> in the <strong>Status</strong> panel.</li><li>Delete the data structure in <strong>Settings → Data structures</strong>, and the codelist in <strong>Settings → Codelists</strong>, if no other indicator uses them.</li></ol><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./indicators-admin.html">Create an indicator in NADA</a>: the same workflow in detail, including creating an indicator without a metadata file</li><li><a href="./indicators.html#choose-a-workflow">Choose a workflow</a>: publish from the Metadata Editor or with the API instead</li><li><a href="./indicators-frontend.html">Catalog frontend</a>: everything users see on an indicator page</li></ul>',53)])])}const O=u(A,[["render",D]]);export{E as __pageData,O as default};
